CREATE TABLE ad.roles (id text PRIMARY KEY, name text NOT NULL);
INSERT INTO ad.roles VALUES ('master','Master'),('rh','Gestão de Pessoas / RH'),('gerente','Gerente'),('gestor','Gestor imediato'),('colaborador','Colaborador');
CREATE TABLE ad.permissions (id text PRIMARY KEY);
INSERT INTO ad.permissions VALUES ('admin'),('employees:read'),('employees:write'),('audit:read');
CREATE TABLE ad.role_permissions (role_id text REFERENCES ad.roles(id), permission_id text REFERENCES ad.permissions(id), PRIMARY KEY(role_id,permission_id));
INSERT INTO ad.role_permissions SELECT r.id,p.id FROM ad.roles r CROSS JOIN ad.permissions p WHERE r.id IN ('master','rh');
INSERT INTO ad.role_permissions VALUES ('gerente','employees:read'),('gestor','employees:read'),('colaborador','employees:read');
CREATE TABLE ad.nuclei (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true);
CREATE TABLE ad.sectors (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text NOT NULL UNIQUE, nucleus_id integer NOT NULL REFERENCES ad.nuclei(id), active boolean NOT NULL DEFAULT true);
CREATE TABLE ad.positions (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true);
CREATE TABLE ad.employees (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text NOT NULL, cpf varchar(11) NOT NULL UNIQUE CHECK(cpf ~ '^[0-9]{11}$'), re text NOT NULL UNIQUE, position_id integer NOT NULL REFERENCES ad.positions(id), status text NOT NULL CHECK(status IN ('ativo','afastado','desligado')), admission_date date NOT NULL, position_start date NOT NULL, level_start date NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ad.users (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, username text NOT NULL UNIQUE, password_hash text NOT NULL, role_id text NOT NULL REFERENCES ad.roles(id), employee_id integer UNIQUE REFERENCES ad.employees(id), active boolean NOT NULL DEFAULT true, must_change_password boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), CHECK(username='master' OR username ~ '^[0-9]{11}$'));
CREATE TABLE ad.managers (user_id integer PRIMARY KEY REFERENCES ad.users(id));
CREATE TABLE ad.supervisors (user_id integer PRIMARY KEY REFERENCES ad.users(id));
CREATE TABLE ad.organizational_links (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, employee_id integer NOT NULL REFERENCES ad.employees(id), sector_id integer NOT NULL REFERENCES ad.sectors(id), manager_id integer REFERENCES ad.managers(user_id), supervisor_id integer REFERENCES ad.supervisors(user_id), started_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz, created_by integer REFERENCES ad.users(id));
CREATE UNIQUE INDEX one_current_link ON ad.organizational_links(employee_id) WHERE ended_at IS NULL;
CREATE INDEX links_manager ON ad.organizational_links(manager_id) WHERE ended_at IS NULL;
CREATE INDEX links_supervisor ON ad.organizational_links(supervisor_id) WHERE ended_at IS NULL;
CREATE TABLE ad.hierarchy_exceptions (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, user_id integer NOT NULL REFERENCES ad.users(id), employee_id integer NOT NULL REFERENCES ad.employees(id), reason text NOT NULL, active boolean NOT NULL DEFAULT true, created_by integer NOT NULL REFERENCES ad.users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,employee_id));
CREATE TABLE ad.sessions (token_hash text PRIMARY KEY, user_id integer NOT NULL REFERENCES ad.users(id), csrf_token text NOT NULL, last_seen timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL);
CREATE INDEX sessions_user ON ad.sessions(user_id);
CREATE TABLE ad.audit (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, user_id integer REFERENCES ad.users(id), action text NOT NULL, entity text NOT NULL, entity_id text, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ad.imports (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, user_id integer NOT NULL REFERENCES ad.users(id), filename text NOT NULL, total integer NOT NULL, report jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ad.settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), password_min_length integer NOT NULL DEFAULT 6 CHECK(password_min_length BETWEEN 6 AND 72), session_idle_minutes integer NOT NULL DEFAULT 30 CHECK(session_idle_minutes BETWEEN 5 AND 480));
INSERT INTO ad.settings DEFAULT VALUES;
